from typing import List

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Compute product and GCD for each prefix
        prefix_prod = [1] * n
        prefix_gcd = [1] * n
        for i in range(1, n):
            prefix_prod[i] = prefix_prod[i-1] * nums[i-1]
            prefix_gcd[i] = prefix_gcd[i-1] * gcd(nums[i-1], prefix_gcd[i-1])

        # Compute LCM for each prefix
        prefix_lcm = [1] * n
        for i in range(1, n):
            prefix_lcm[i] = prefix_lcm[i-1] * nums[i-1]
            prefix_lcm[i] = prefix_lcm[i] // gcd(prefix_lcm[i-1], prefix_gcd[i-1])

        # Find the longest subarray where product == lcm * gcd
        max_len = 0
        for i in range(n):
            for j in range(i + 1, n):
                if prefix_prod[j] == prefix_lcm[j] * prefix_gcd[j]:
                    max_len = max(max_len, j - i + 1)

        return max_len
