class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)

        # Count consecutive strictly increasing subarrays
        increasing = 0
        current_increasing = 0
        for i in range(n):
            if i > 0 and nums[i] > nums[i - 1]:
                current_increasing += 1
            else:
                current_increasing = 0
            increasing += current_increasing

        # Count consecutive strictly decreasing subarrays
        decreasing = 0
        current_decreasing = 0
        for i in range(n):
            if i > 0 and nums[i] < nums[i - 1]:
                current_decreasing += 1
            else:
                current_decreasing = 0
            decreasing += current_decreasing

        return max(increasing, decreasing)
