def solve():
    s = input()
    n = len(s)

    # Condition 1: Length must be even
    if n % 2 != 0:
        print("No")
        return

    # Condition 2: For each i from 1 to n/2, (2i-1)-th and 2i-th characters are equal
    # This means s[i-1] == s[i] for i in 1..n/2
    if s[0] != s[1]:
        print("No")
        return
    for i in range(1, n // 2):
        if s[i] != s[i+1]:
            print("No")
            return

    # Condition 3: Every character appears exactly 0 or 2 times
    char_counts = {}
    for char in s:
