class Solution:
    def getSmallestString(self, s: str) -> str:
        # Count the number of odd and even digits
        odd_count = 0
        even_count = 0
        for char in s:
            if char == '1' or char == '3' or char == '5' or char == '7' or char == '9':
                odd_count += 1
            else:
                even_count += 1

        # If there are no odd digits, the string is already sorted
        if odd_count == 0:
            return s

        # If there are odd digits, we need to swap adjacent pairs of odd digits
        # to get the lexicographically smallest result.
        # We can iterate through the string and swap odd digits with their neighbors
        # if the neighbor is also odd.
        result = s
        for i in range(len(result) - 1):
            if result[i] == result[i + 1] and result[i] == result[i + 1] + 2:
                # Both are odd, swap them
                result[i], result[i + 1] = result[i + 1], result[i]

        return result
