class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        if not words or not target:
            return 0

        # Count occurrences of each character in target
        char_counts = {}
        for c in target:
            char_counts[c] = char_counts.get(c, 0) + 1

        # For each word, count how many times each character appears
        word_char_counts = {}
        for word in words:
            word_char_counts = {}
            for c in word:
                word_char_counts[c] = word_char_counts.get(c, 0) + 1
            # Keep only characters that appear in target
            for c in target:
                if c in word_char_counts:
                    word_char_counts[c] += word_char_counts[c]

        # Find the maximum number of times any character appears in target
        max_count = max(char_counts.values()) if char_counts else 0

        if max_count == 0:
            return 0

        # The answer is the sum of (max_count - count) for each word
        return sum(max_count - word_char_counts[c] for c in target if word_char_counts[c] > 0)
