    def calculateScore(self, s: str) -> int:
        # Map each character to its mirror counterpart
        mirror_map = {c: c[::-1] for c in set(s)}

        # Initialize a set to keep track of marked indices
        marked_indices = set()

        total_score = 0

        for i, char in enumerate(s):
            # Find the closest unmarked index j < i such that s[j] is the mirror of s[i]
            for j in range(i - 1, -1, -1):
                if j not in marked_indices and s[j] == mirror_map[char]:
                    total_score += i - j
                    marked_indices.add(i)
                    marked_indices.add(j)
                    break

