class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m = len(grid)
        n = len(grid[0])

        # Check if we can even reach the bottom-right cell
        if health < m + n:
            return False

        # If health is less than 1, we can't reach the cell
        if health < 1:
            return False

        # Calculate the minimum health needed to reach the bottom-right cell
        # Each safe step reduces health by 1, so we need health = m + n - 1
        min_health = m + n - 1

        # If current health is less than min_health, return false
        if health < min_health:
            return False

        # BFS to find a valid path
        queue = [(0, 0, 0)]  # (row, col, current_health)
        visited = set()

        while queue:
            r, c, health = queue.pop(0)

            if (r, c) == (m - 1, n - 1):
                return True

            # Check all 4 directions
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc

                # Check bounds
                if 0 <= nr < m and 0 <= nc < n:
