class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Build adjacency list: city -> list of next cities
        adj = [[] for _ in range(n)]
        for i in range(n - 1):
            adj[i].append(i + 1)

        # BFS to find shortest path from 0 to n-1
        # We maintain a queue of (current_city, current_dist)
        # dist array stores the shortest distance from 0 to each city
        dist = [float('inf')] * n
        dist[0] = 0
        queue = [0]
        visited = [False] * n
        visited[0] = True

        while queue:
            curr = queue.pop(0)
            if curr == n - 1:
                break
            if not visited[curr]:
                visited[curr] = True
                for next_city in adj[curr]:
                    if not visited[next_city]:
                        dist[next_city] = dist[curr] + 1
                        queue.append(next_city)

        # Process queries
        result = []
        for u, v in queries:
            if dist[v] == float('inf'):
                result.append(float('inf'))
            else:
                result.append(dist[v])

        return result
