from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i] = maximum score to reach index i
        dp = [0] * n
        dp[0] = nums[0] * 0  # score = 0 * 0 = 0

        for i in range(1, n):
            # Try all possible jumps from i-1
            for j in range(i - 1, i - 1, -1):
                if j < 0:
                    continue
                score = (j - i) * nums[i]
                dp[i] = max(dp[i], dp[j] + score)

        return dp[n - 1]
