from typing import List
from math import gcd
from math import lcm

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Calculate the base score if we keep all elements
        base_score = 1
        for x in nums:
            base_score *= lcm(x, x)  # LCM of x with itself is x
        base_score *= gcd(x, x)  # GCD of x with itself is x

        # Try removing each element to see if we can get a higher score
        for i in range(n):
            # If we remove nums[i], compute the score with the rest
            if i == 0:
                current_score = 0
            else:
                current_score = 1
            for j in range(i + 1, n):
                current_score *= lcm(nums[j], nums[j])  # LCM of nums[j] with itself is nums[j]
            current_score *= gcd(nums[j], nums[j])  # GCD of nums[j] with itself is nums[j]
            if current_score > base_score:
                base_score = current_score

        return base_score
