from typing import List
from collections import Counter

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        # Count the frequency of each character in each string
        char_counts = [[] for _ in range(26)]
        for s in arr:
            for c in s:
                char_counts[c - ord('a')].append(s)

        # Build a map from string to list of its indices
        string_indices = {s: [] for s in arr}
        for i, s in enumerate(arr):
            string_indices[s].append(i)

        # For each string, find the shortest non-occurrence
        result = []
        for s in arr:
            # Count how many times each character appears in s
            char_counts[s] = Counter(s)

            # Try all possible substrings
            min_len = float('inf')
            answer = ""

            for i in range(len(s) - len(s) + 1):
                substr = s[i:i + len(s)]
                if substr not in string_indices:
                    if len(substr) < min_len:
                        min_len = len(substr)
                        answer = substr
                    elif len(substr) == min_len and answer != substr:
                        # Lexicographically smaller than current answer
                        answer = substr

            if min_len == float('inf'):
                result.append("")
            else:
                result.append(answer)

        return result
