class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        m = len(properties[0])

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if i != j:
                    if properties[i][j] >= k:
                        adj[i].append(j)
                        adj[j].append(i)

        # Count connected components using BFS/DFS
        components = 0
        visited = [False] * n

        for i in range(n):
            if not visited[i]:
                components += 1
                visited = [True] * n
                queue = [i]
                while queue:
                    node = queue.pop(0)
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components
