class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Handle edge case with single element
        if n == 1:
            return grid[0]

        # Create a temporary grid to store the sorted result
        result = [[0] * n for _ in range(n)]

        # Define the two triangles
        # Bottom-left triangle: indices (i, j) where i <= j
        # Top-right triangle: indices (i, j) where i >= j

        # Fill bottom-left triangle with non-increasing order
        for i in range(n):
            for j in range(i):
                result[i][j] = grid[i][j]

        # Fill top-right triangle with non-decreasing order
        for i in range(n - 1):
            for j in range(i + 1):
                result[i][j] = grid[i][j]

        # Now fill the rest with the sorted values
        for i in range(n):
            for j in range(i + 1, n):
                result[i][j] = grid[i][j]

        return result
```

